"""Familia politica de un bloque o partido a partir de su nombre. La usan build.py (legisladores) y
02_procesar.py (votaciones nominales), para que los dos clasifiquen igual."""
import re, unicodedata

FAM = [  # order matters: first match wins
    ("sin bloque", r"^SIN BLOQUE|NO INTEGRA BLOQUE"),
    ("izquierda", r"IZQUIERDA|TRABAJADORES|\bPTS\b|\bMST\b|OBRERO|SOCIALISMO|COMUNISTA|\bMAS\b|AUTODETERMINACION"),
    ("LLA / libertarios", r"LIBERTAD AVANZA|LIBERTARI|AVANZA LIBERTAD"),
    ("UCR / Cambiemos / JxC", r"RADICAL|\bUCR\b|CAMBIEMOS|JUNTOS POR EL CAMBIO|\bPRO\b|PROPUESTA REPUBLICANA|COALICION CIVICA|\bARI\b|"
                               r"AFIRMACION PARA UNA REPUBLICA|ALIANZA POR EL TRABAJO|EVOLUCION|ACUERDO CIVICO|CAMBIA MENDOZA|"
                               r"FRENTE CIVICO Y SOCIAL|CAMBIO FEDERAL|DEMOCRACIA PARA SIEMPRE|HACEMOS COALICION|JUNTOS POR|UNION PARA VIVIR MEJOR|\bGEN\b|RECREAR|"
                               r"FRENTE PROGRESISTA|FUERZA CIVICA|ECO |FRENTE JUJENO"),
    ("peronismo", r"JUSTICIALIS|PERONIS|\bPJ\b|VICTORIA|FRENTE DE TODOS|FRENTE TODOS|UNION POR LA PATRIA|UNIDAD CIUDADANA|FRENTE RENOVADOR|"
                  r"FUERZA PATRIA|CONCERTACION|FREJUPO|FRENTE GRANDE|FREPASO|PAIS SOLIDARIO|NUEVO ENCUENTRO|FEDERAL UNIDOS|UNIDOS POR UNA NUEVA|"
                  r"PERONISMO|LEALTAD|MOVIMIENTO EVITA|FRENTE DE LA CONCORDIA|RENOVADOR DE LA CONCORDIA|FRENTE CIVICO POR SANTIAGO|"
                  r"NACIONAL Y POPULAR|CONVICCION FEDERAL|UNIDAD FEDERAL$|JUSTICIA SOCIAL|FEDERALISMO Y LIBERACION|CELESTE Y BLANCO|JUSTICIA UNION Y LIBERTAD|"
                  r"UNION POR CORDOBA|FREJULI|COMPROMISO FEDERAL|ARGENTINA FEDERAL|PAIS FEDERAL|FRENTE POPULAR|FRENTE DE LA ESPERANZA|UNION POR CHACO|UNION POR ENTRE RIOS|CORDOBA FEDERAL|HACEMOS POR|CONSENSO FEDERAL|SOLIDARIDAD E IGUALDAD|UNIDAD POPULAR|PATRIA"),
    ("partidos provinciales", r"NEUQUINO|NEUQUINIDAD|JUJENO|LIGA DEL INTERIOR|PARTIDO NUEVO|FRENTE CIVICO - CORDOBA|FRENTE CIVICO$|DEFENDAMOS CORDOBA|UNIDAD FEDERALISTA|POR SANTA CRUZ|SANTIAGO VIABLE|SALTENOS|FUERZA ENTRE RIOS|AVANZAR SAN LUIS|FUEGUINO|BLOQUISTA|LIBERAL|AUTONOMISTA|RENOVADOR DE SALTA|FUERZA REPUBLICANA|CRUZADA RENOVADORA|"
                              r"DEMOCRATA|PRODUCCION Y TRABAJO|ACCION CHAQUENA|VECINALISTA|MISIONER|SANTA FE FEDERAL|INNOVACION FEDERAL|"
                              r"PROVINCIAS UNIDAS|JUNTOS SOMOS RIO NEGRO|DESARROLLO Y JUSTICIA|CHUBUT|SALTA|CATAMARCA|CORRIENTES|MENDOZA"),
    ("centro-derecha no JxC", r"CENTRO DEMOCRATICO|UCEDE|ACCION POR LA REPUBLICA|\bMODIN\b|DIGNIDAD Y LA INDEPENDENCIA|RECREAR|FEDERALISMO Y LIBERTAD"),
    ("socialismo / centroizq no peronista", r"SOCIALISTA|FRENTE AMPLIO PROGRESISTA|UNEN|INTRANSIGENTE|DEMOCRATA CRISTIAN|LIBRES DEL SUR|PROYECTO SUR|SI POR LA UNIDAD|MOVIMIENTO LIBRES"),
]
def familia(s):
    s = " ".join(unicodedata.normalize("NFKD", str(s)).encode("ascii", "ignore").decode().upper().split())
    for fam, rx in FAM:
        if re.search(rx, s): return fam
    return "otros / sin clasificar"
